-- VIEW: câu truy vấn được đặt tên, dùng lại như bảng
CREATE VIEW v_customer_revenue AS
SELECT c.id, c.name, COUNT(DISTINCT o.id) AS orders
FROM customers c LEFT JOIN orders o ON o.customer_id = c.id
GROUP BY c.id;

-- TRIGGER: ghi nhật ký mỗi khi giá sản phẩm thay đổi
CREATE TABLE price_log (product_id INTEGER, old_price INTEGER, new_price INTEGER);
CREATE TRIGGER trg_price_change AFTER UPDATE OF price ON products
BEGIN
  INSERT INTO price_log VALUES (OLD.id, OLD.price, NEW.price);
END;

UPDATE products SET price = price + 1000 WHERE id = 6;
SELECT * FROM price_log;

